L000850	\section{Landau Theory}\label{sec:3}
L000851	\label{sec:Landau}
L000852	
L000853	In this section, we derive an effective Landau functional for cubic perovskites starting from the parent space group $Pm\bar{3}m$, with an emphasis on the $R$-point structural instability at $\mathbf{q}=(\pi,\pi,\pi)$. This high-symmetry parent phase is shared by a broad class of antiferroaxial altermagnetic materials, including perovskite oxides (e.g., KMnF$_3$, LaCrO$_3$) and transition-metal trifluorides (e.g., FeF$_3$).
L000854	
L000855	
L000856	\subsection{Order parameters and symmetry}
L000857	We introduce the following order parameters, classified by the irreducible representations (IRs) of the parent space group at the $R$ point:
L000858	
L000859	\begin{enumerate}
L000860	\item \textbf{N\'{e}el order.} The antiferromagnetic order parameter is denoted by the spin-space vector $\mathbf N$ and transforms as
L000861	$\mathbf N\sim R_1^+$.
L000862	Throughout this section, we take the zero SOC limit, the direction of $\mathbf N$ is decoupled from the real space, and we treat its amplitude $N\equiv|\mathbf N|$ as the relevant Landau variable.
L000863	
L000864	\item \textbf{Antiferroaxial order.} The antiferroaxial (counter-rotating) distortion is described by a three-component axial order parameter
L000865	$\mathbf G=(G_x,G_y,G_z)$ transforming as $\mathbf G\sim R_1^+\otimes\Gamma_4^+(T_{1g})= R_4^+$.
L000866	
L000867	\item \textbf{Elastic strains.}
L000868	Since $\mathbf G$ is a structural order parameter, the lattice strains $\varepsilon_{ij}$ constitute additional symmetry-allowed secondary degrees of freedom and generally couple to $\mathbf G$ via rotostriction, thereby renormalizing the effective Landau coefficients and generating anisotropy.
L000869	We therefore include the symmetric strain tensor $\varepsilon_{ij}$ and decompose it into symmetry-adapted combinations of the cubic point group $O_h$:
L000870	\begin{align}
L000871	& A_{1g}: && \varepsilon_v=\varepsilon_{xx}+\varepsilon_{yy}+\varepsilon_{zz}, \\
L000872	& E_g: && \varepsilon_1=\varepsilon_{zz}-\tfrac{1}{2}(\varepsilon_{xx}+\varepsilon_{yy}),\qquad
L000873	\varepsilon_2=\tfrac{\sqrt{3}}{2}(\varepsilon_{yy}-\varepsilon_{xx}),\\
L000874	& T_{2g}: && (\varepsilon_{yz},\varepsilon_{xz},\varepsilon_{xy}).
L000875	\end{align}
L000876	
L000877	\item \textbf{Rank-4 (g-wave) magnetic multipoles.}
L000878	The antiferroaxial altermagnetic order is diagnosed by the rank $\ell=4$ magnetic multipole in the $T_{1g}$ spatial channel.
L000879	We choose a convenient basis
L000880	\begin{equation}
L000881	(\mathbf O_1,\mathbf O_2,\mathbf O_3)
L000882	=(\mathbf O_{yz(y^2-z^2)},\ \mathbf O_{xz(x^2-z^2)},\ \mathbf O_{xy(x^2-y^2)}),
L000883	\end{equation}
L000884	where each $\mathbf O_i$ is a spin-space vector defined microscopically by
L000885	$\mathbf O_{xy(x^2-y^2)}\equiv \int d^3r\, xy(x^2-y^2)\,\mathbf m(\mathbf r)$,
L000886	and similarly for the other components.
L000887	\end{enumerate}
L000888	Because $\mathbf N$ and $\mathbf O_i$ are both vectors in spin space, all dot products below are taken in spin space.
L000889	
L000890	\subsection{Landau free energy}
L000891	The total free-energy density, which can be constructed using the symmetry analysis tools in the ISOTROPY software suite~\cite{stokes2016isosubgroup,hatch2003invariants}, is given by
L000892	\begin{equation}
L000893	\mathcal F = \mathcal F_{N,G}+\mathcal F_{\varepsilon}+\mathcal F_{G\varepsilon}+\mathcal F_{N,G,O}.
L000894	\end{equation}
L000895	
L000896	We first collect the magnetic and antiferroaxial contributions. Keeping terms up to quartic order, we write
L000897	\begin{align}
L000898	\mathcal F_{N,G}
L000899	=&\ \alpha_N \mathbf N^2 + \beta_N (\mathbf N^2)^2
L000900	+ \alpha_G \mathbf G^2 + \beta_{G1}(\mathbf G^2)^2
L000901	+ \beta_{G2}\!\left(G_x^2G_y^2+G_x^2G_z^2+G_y^2G_z^2\right)
L000902	+ \lambda_{NG}\mathbf N^2\mathbf G^2,
L000903	\label{eq:SM_F_NG}
L000904	\end{align}
L000905	where $\mathbf G^2=G_x^2+G_y^2+G_z^2$.
L000906	
L000907	The elastic energy at the harmonic level allowed by $O_h$ is
L000908	\begin{equation}
L000909	\mathcal F_{\varepsilon}
L000910	=C_0\varepsilon_v^2
L000911	+C_1(\varepsilon_1^2+\varepsilon_2^2)
L000912	+C_2(\varepsilon_{yz}^2+\varepsilon_{xz}^2+\varepsilon_{xy}^2).
L000913	\label{eq:SM_F_elastic}
L000914	\end{equation}
L000915	
L000916	The bilinear coupling between the quadratic form of $\mathbf G$ and the strain irreducible representations is
L000917	\begin{align}
L000918	\mathcal F_{G\varepsilon}
L000919	=&\ \lambda_1\!\left[
L000920	\frac{1}{\sqrt{3}}\left(2G_z^2-G_x^2-G_y^2\right)\varepsilon_1
L000921	+\left(G_x^2-G_y^2\right)\varepsilon_2
L000922	\right]
L000923	+\lambda_2\left(G_yG_z\,\varepsilon_{yz}+G_xG_z\,\varepsilon_{xz}+G_xG_y\,\varepsilon_{xy}\right).
L000924	\label{eq:SM_F_rotostriction}
L000925	\end{align}
L000926	An additional $A_{1g}$ coupling $\propto \mathbf G^2\varepsilon_v$ is symmetry-allowed and can be absorbed into a redefinition of $\beta_{G1}$.
L000927	
L000928	Finally, the lowest-order invariant coupling among $\mathbf N$, $\mathbf G$, and the $T_{1g}$ multipoles reads
L000929	\begin{equation}
L000930	\mathcal F_{N,G,O}
L000931	=\lambda_O\left(\mathbf O_1^2+\mathbf O_2^2+\mathbf O_3^2\right)
L000932	+g\,\mathbf N\cdot\left(G_x\mathbf O_1+G_y\mathbf O_2+G_z\mathbf O_3\right).
L000933	\label{eq:SM_F_NGO}
L000934	\end{equation}
L000935	Once both $\mathbf N\neq 0$ and $\mathbf G\neq 0$ develop, this term induces the $g$-wave multipole as $\mathbf O_i\propto \mathbf N G_i$, implying an antiferroaxial control of the altermagnetic spin splitting.
L000936	
L000937	
L000938	\subsection{Integrating out secondary degrees of freedom}
L000939	We now derive an effective free energy in terms of the primary structural order parameter $\mathbf G$ by eliminating
L000940	$\mathbf O$, $\mathbf N$ (amplitude), and the strains $\varepsilon$ through their saddle-point conditions.
L000941	
L000942	\subsubsection{Eliminating the multipoles $\mathbf O$}
L000943	Minimizing Eq.~\eqref{eq:SM_F_NGO} with respect to $\mathbf O_i$ gives
L000944	\begin{equation}
L000945	\frac{\partial \mathcal F}{\partial \mathbf O_i}=0
L000946	\quad\Rightarrow\quad
L000947	\mathbf O_i=-\frac{g}{2\lambda_O}\,\mathbf N\,G_i.
L000948	\label{eq:SM_O_constitutive}
L000949	\end{equation}
L000950	Substituting back into Eq.~\eqref{eq:SM_F_NGO} yields a negative biquadratic contribution
L000951	\begin{equation}
L000952	\mathcal F_{N,G,O}\ \to\ -\frac{g^2}{4\lambda_O}\,\mathbf N^2\mathbf G^2.
L000953	\end{equation}
L000954	Therefore the effective $\mathbf N^2\mathbf G^2$ coupling becomes
L000955	\begin{equation}
L000956	\Lambda \equiv \lambda_{NG}-\frac{g^2}{4\lambda_O}.
L000957	\label{eq:SM_Lambda_def}
L000958	\end{equation}
L000959	
L000960	\subsubsection{Eliminating the N\'{e}el amplitude $N$}
L000961	After eliminating $\mathbf O$, the $N$-dependent part is
L000962	\begin{equation}
L000963	\mathcal F_N
L000964	=\alpha_N \mathbf N^2+\beta_N(\mathbf N^2)^2+\Lambda\,\mathbf N^2\mathbf G^2.
L000965	\end{equation}
L000966	Stationarity $\partial\mathcal F/\partial \mathbf N=0$ gives
L000967	\begin{equation}
L000968	\alpha_N\mathbf N + 2\beta_N\mathbf N^2\mathbf N +\Lambda\,\mathbf G^2\mathbf N=0.
L000969	\end{equation}
L000970	In the magnetically ordered phase ($\mathbf N\neq 0$) this yields
L000971	\begin{equation}
L000972	\mathbf N^2=-\frac{\alpha_N+\Lambda\,\mathbf G^2}{2\beta_N}.
L000973	\label{eq:SM_N2}
L000974	\end{equation}
L000975	Substituting Eq.~\eqref{eq:SM_N2} back contributes the standard negative-definite term
L000976	\begin{equation}
L000977	\mathcal F_N \ \to\ -\frac{(\alpha_N+\Lambda\,\mathbf G^2)^2}{4\beta_N}
L000978	=\mathrm{const.}-\frac{\alpha_N\Lambda}{2\beta_N}\mathbf G^2-\frac{\Lambda^2}{4\beta_N}(\mathbf G^2)^2.
L000979	\end{equation}
L000980	
L000981	\subsubsection{Eliminating strains}
L000982	Minimizing $\mathcal F_\varepsilon+\mathcal F_{G\varepsilon}$ with respect to each strain component gives
L000983	\begin{equation}
L000984	\begin{split}
L000985	\varepsilon_1&=-\frac{\lambda_1}{2C_1}\frac{1}{\sqrt{3}}\left(2G_z^2-G_x^2-G_y^2\right),\qquad
L000986	\varepsilon_2=-\frac{\lambda_1}{2C_1}\left(G_x^2-G_y^2\right), \\
L000987	\varepsilon_{ij}&=-\frac{\lambda_2}{2C_2}G_iG_j,\qquad (i\neq j;\ i,j\in\{x,y,z\}),
L000988	\end{split}
L000989	\label{eq:SM_strain_eq}
L000990	\end{equation}
L000991	while $\varepsilon_v$ decouples in the present truncation.
L000992	Substituting \eqref{eq:SM_strain_eq} back yields the strain-mediated quartic renormalization
L000993	\begin{equation}
L000994	\Delta \mathcal F_{\rm strain}
L000995	=-\frac{\lambda_1^2}{3C_1}(\mathbf G^2)^2+\left(\frac{\lambda_1^2}{C_1}-\frac{\lambda_2^2}{4C_2}\right)\left(G_x^2G_y^2+G_x^2G_z^2+G_y^2G_z^2\right).
L000996	\end{equation}
L000997	
L000998	\subsection{Effective free energy for $\mathbf G$}
L000999	Collecting the above results, the effective free energy takes the cubic-invariant form
L001000	\begin{equation}
L001001	\mathcal F_{\rm eff}(\mathbf G)
L001002	=\alpha_{\rm eff}\mathbf G^2
L001003	+\beta_{1,{\rm eff}}(\mathbf G^2)^2
L001004	+\beta_{2,{\rm eff}}\left(G_x^2G_y^2+G_x^2G_z^2+G_y^2G_z^2\right),
L001005	\label{eq:SM_Feff}
L001006	\end{equation}
L001007	with renormalized coefficients
L001008	\begin{align}
L001009	\alpha_{\rm eff}&=\alpha_G-\frac{\alpha_N}{2\beta_N}\Lambda,\\
L001010	\beta_{1,{\rm eff}}&=\beta_{G1}-\frac{\Lambda^2}{4\beta_N}-\frac{\lambda_1^2}{3C_1},\\
L001011	\beta_{2,{\rm eff}}&=\beta_{G2}+\frac{\lambda_1^2}{C_1}-\frac{\lambda_2^2}{4C_2}.
L001012	\label{eq:SM_coeffs}
L001013	\end{align}
L001014	The anisotropy parameter $\beta_{2,{\rm eff}}$ determines the orientation of $\mathbf G$ and therefore the form of the induced $g$-wave multipole.
L001015	
L001016	\subsection{Phase I: $\mathbf G \parallel [001]$ (planar $g$-wave)}
L001017	For $\beta_{2,{\rm eff}}>0$, the minimum is achieved when $\mathbf G$ points along a principal axis, e.g.
L001018	$\mathbf G=(0,0,G_z)$.
L001019	Then Eq.~\eqref{eq:SM_Feff} reduces to
L001020	\begin{equation}
L001021	\mathcal F_{\rm eff}=\alpha_{\rm eff}G_z^2+\beta_{1,{\rm eff}}G_z^4,
L001022	\end{equation}
L001023	with $G_z^2=-\alpha_{\rm eff}/(2\beta_{1,{\rm eff}})$ in the ordered phase.
L001024	Stability against transverse fluctuations requires $\beta_{1,{\rm eff}}>0$ and $\beta_{2,{\rm eff}}>0$.
L001025	
L001026	The secondary orders follow from Eq.~\eqref{eq:SM_O_constitutive}, Eq.~\eqref{eq:SM_N2}, and Eq.~\eqref{eq:SM_strain_eq}:
L001027	\begin{equation}
L001028	\mathbf O_3=-\frac{g}{2\lambda_O}\mathbf N G_z\neq 0,\quad
L001029	\mathbf O_1=\mathbf O_2=0,\quad \mathbf{N}^2=-\frac{\alpha_N+\Lambda G_z^2}{2\beta_N},
L001030	\end{equation}
L001031	indicating a planar $g$-wave multipole with $xy(x^2-y^2)$ spin-splitting form.
L001032	The equilibrium strains are
L001033	\begin{equation}
L001034	\varepsilon_2=\varepsilon_{xy}=\varepsilon_{xz}=\varepsilon_{yz}=0,\qquad
L001035	\varepsilon_1=-\frac{\lambda_1}{C_1\sqrt{3}}G_z^2.
L001036	\end{equation}
L001037	
L001038	\textit{When coupling to uniaxial stress along $[001]$.}
L001039	Applying a uniaxial stress $\sigma_z$ adds
L001040	$\mathcal F_{\rm stress}=-\sigma_z\varepsilon_{zz}$.
L001041	Using $\varepsilon_{zz}=\varepsilon_v/3+2\varepsilon_1/3$, only $\varepsilon_1$ is relevant here.
L001042	The minimization condition becomes
L001043	\begin{equation}
L001044	2C_1\varepsilon_1+\frac{\lambda_1}{\sqrt{3}}(2G_z^2)-\frac{2}{3}\sigma_z=0
L001045	\quad\Rightarrow\quad
L001046	\varepsilon_1=-\frac{\lambda_1}{C_1\sqrt{3}}G_z^2+\frac{\sigma_z}{3C_1}.
L001047	\end{equation}
L001048	Substituting this solution back, the stress generates a linear shift of the quadratic coefficient,
L001049	\begin{equation}
L001050	\alpha_{\rm eff}(\sigma_z)=\alpha_{\rm eff}(0)+\frac{2\lambda_1}{3\sqrt{3}C_1}\sigma_z.
L001051	\end{equation}
L001052	This leads to the relation $G_z \propto \sqrt{\sigma_z - \sigma_c}$, valid for $\lambda_1 \sigma_z > 0$, where the critical threshold is given by $\sigma_c = -\frac{3\sqrt{3}C_1}{2\lambda_1}\alpha_{\rm eff}(0)$. This result demonstrates that the antiferroaxial order---and consequently the altermagnetism---can be mechanically controlled on or off. This scenario is realized in KMnF$_3$ [Fig.~\ref{fig:KMnF3}(d)].
L001053	
L001054	\subsection{Phase II: $\mathbf G \parallel [111]$ (bulk $g$-wave)}
L001055	For $\beta_{2,{\rm eff}}<0$, the minimum is achieved for the body-diagonal configuration
L001056	$G_x=G_y=G_z=G/\sqrt{3}$,
L001057	yielding
L001058	\begin{equation}
L001059	\mathcal F_{\rm eff}=\alpha_{\rm eff}G^2+\beta_{\rm eff}G^4,\qquad
L001060	\beta_{\rm eff}\equiv \beta_{1,{\rm eff}}+\frac{1}{3}\beta_{2,{\rm eff}},
L001061	\end{equation}
L001062	and $G^2=-\alpha_{\rm eff}/(2\beta_{\rm eff})$.
L001063	The induced multipoles are equal-amplitude
L001064	\begin{equation}
L001065	\mathbf O_1=\mathbf O_2=\mathbf O_3=-\frac{g}{2\lambda_O}\mathbf N\frac{G}{\sqrt{3}},
L001066	\end{equation}
L001067	corresponding to the coherent superposition
L001068	$yz(y^2-z^2)+zx(z^2-x^2)+xy(x^2-y^2)=(x+y+z)(x-y)(y-z)(z-x)$, i.e., the bulk $g$-wave form.
L001069	
L001070	In this phase the $E_g$-type strains vanish, hence $\varepsilon_1=\varepsilon_2=0$, while the $T_{2g}$ shear strains satisfy
L001071	\begin{equation}
L001072	\varepsilon_{xy}=\varepsilon_{yz}=\varepsilon_{xz}\equiv \varepsilon_s
L001073	=-\frac{\lambda_2}{6C_2}G^2.
L001074	\end{equation}
L001075	
L001076	\textit{Stress along $[111]$ and anharmonic elasticity.}
L001077	Under uniaxial stress $\sigma_{111}$, the relevant combination is
L001078	$\varepsilon_{111}=\frac{1}{3}\varepsilon_v+2\varepsilon_s$,
L001079	giving $\mathcal F_{\rm stress}=-(\sigma_{111}/3)\varepsilon_v-2\sigma_{111}\varepsilon_s$.
L001080	Because $\varepsilon_s\neq 0$, the lowest shear-anharmonic invariant
L001081	$C_3\varepsilon_{xy}\varepsilon_{yz}\varepsilon_{xz}=C_3\varepsilon_s^3$
L001082	contributes. The shear-sector free energy becomes
L001083	\begin{equation}
L001084	\mathcal F_s
L001085	=3C_2\varepsilon_s^2+C_3\varepsilon_s^3+\lambda_2G^2\varepsilon_s-2\sigma_{111}\varepsilon_s.
L001086	\end{equation}
L001087	Minimizing with respect to $\varepsilon_s$ gives
L001088	\begin{equation}
L001089	(\lambda_2G^2-2\sigma_{111})+6C_2\varepsilon_s+3C_3\varepsilon_s^2=0.
L001090	\end{equation}
L001091	For weak anharmonicity $|C_3|\ll C_2$, the solution satisfying $\varepsilon_s\to 0$ when $G,\sigma_{111}\to 0$ reads
L001092	\begin{equation}
L001093	\varepsilon_s(\sigma_{111})
L001094	\simeq \frac{2\sigma_{111}-\lambda_2G^2}{6C_2}
L001095	-\frac{C_3}{72C_2^3}\left(2\sigma_{111}-\lambda_2G^2\right)^2.
L001096	\end{equation}
L001097	Substituting back, the stress effectively renormalizes the quadratic and quartic coefficients (up to $O(G^4)$ and keeping the leading stress dependence):
L001098	\begin{align}
L001099	\alpha_{\rm eff}(\sigma_{111})
L001100	&=\alpha_{\rm eff}(0)+\frac{\lambda_2}{3C_2}\sigma_{111}
L001101	-\frac{C_3\lambda_2}{18C_2^3}\sigma_{111}^2,\\
L001102	\beta_{\rm eff}(\sigma_{111})
L001103	&=\beta_{\rm eff}(0)+\frac{C_3\lambda_2^2}{36C_2^3}\sigma_{111},
L001104	\end{align}
L001105	which implies a generically non-monotonic (parabolic) dependence of $G^2$ on $\sigma_{111}$ (or strain, as stress and strain satisfy Hooke's law in the small-strain limit).
L001106	This provides an analytic rationale for the parabolic strain dependence of the antiferroaxial rotation amplitude observed in FeF$_3$, as shown in Fig.~\ref{fig:strain}.
L001107	
L001108	\begin{figure*}[htbp]
L001109	\includegraphics[width=0.6\textwidth]{strain.pdf}
L001110	\caption{\label{fig:strain} Dependence of the squared antiferroaxial rotation angle $\theta^2$ on the applied uniaxial strain $\varepsilon_{111}$ in FeF$_3$, obtained from DFT calculations. The numerical results are well fit to the quadratic relation $\theta^2=7085-144\varepsilon_{111}+0.7511\varepsilon_{111}^2$, where $\theta$ is expressed in degrees and the strain $\varepsilon_{111}$ is expressed in percentage.} \end{figure*}
